// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.productivity.reminderimport timber.log.Timberimport android.app.NotificationManagerimport android.content.BroadcastReceiverimport android.content.Contextimport android.content.Intentimport android.os.Buildimport androidx.work.OneTimeWorkRequestBuilderimport androidx.work.WorkManagerimport androidx.work.workDataOfimport java.util.concurrent.TimeUnit/** * NOUS — Reminder Action Receiver (Module 14 v1.2 — Step 14.2). * * REAL [BroadcastReceiver] that handles SNOOZE / DISMISS button taps * from the reminder notification (posted by [ReminderWorker]). * * ## How it gets called * * The notification built in [ReminderWorker.showReminderNotification] * registers two action buttons, each backed by a PendingIntent that * targets this receiver: * *   - SNOOZE  → [ACTION_SNOOZE]  → re-schedules the work with [DEFAULT_SNOOZE_MS] delay. *   - DISMISS → [ACTION_DISMISS] → cancels the WorkManager work + clears the notification. * * All PendingIntents that target this receiver were built with * `FLAG_IMMUTABLE` on API 31+ (mandatory per strategy v1.2 §"Improvement 2"). * * ## Snooze semantics * * Snooze cancels the existing WorkManager work (by tag) and enqueues a * fresh `OneTimeWorkRequest` with the same reminder payload, but with * `initialDelay = DEFAULT_SNOOZE_MS`. The [ReminderStore] is updated so * `getActiveReminders()` reflects the new trigger time. * * Snooze count is enforced by [ReminderEngine.snoozeReminder] — once * `snoozeCount >= maxSnoozeCount`, the SNOOZE button is rejected (the * notification is dismissed instead). * * @see <a href="docs/strategy/module-14-productivity-strategy-v1.2-final.md">§Polish 2 (snooze)</a> */class ReminderActionReceiver : BroadcastReceiver() {    companion object {        private const val TAG = "ReminderAction"        /** Broadcast action for the SNOOZE button. */        const val ACTION_SNOOZE = "com.roshan.persona.REMINDER_SNOOZE"        /** Broadcast action for the DISMISS button. */        const val ACTION_DISMISS = "com.roshan.persona.REMINDER_DISMISS"        /** Intent extra: reminder ID. */        const val EXTRA_REMINDER_ID = "reminder_id"        /** Intent extra: reminder label. */        const val EXTRA_LABEL = "label"        /** Intent extra: encrypted body IV (Base64). */        const val EXTRA_IV = "iv"        /** Intent extra: encrypted body ciphertext (Base64). */        const val EXTRA_CIPHERTEXT = "ciphertext"        /** Default snooze duration (5 minutes). */        const val DEFAULT_SNOOZE_MS = ReminderInfo.DEFAULT_SNOOZE_MS        /** WorkManager tag prefix used for reminder work (matches [ReminderEngine]). */        const val WORK_TAG_PREFIX = "reminder_"    }    override fun onReceive(context: Context, intent: Intent) {        val action = intent.action ?: return        val reminderId = intent.getStringExtra(EXTRA_REMINDER_ID) ?: "unknown"        val label = intent.getStringExtra(EXTRA_LABEL) ?: "Reminder"        val iv = intent.getStringExtra(EXTRA_IV) ?: ""  // HIGH FIX: Default empty IV        val ciphertext = intent.getStringExtra(EXTRA_CIPHERTEXT) ?: ""  // HIGH FIX: Default empty ciphertext        Timber.tag(TAG).i("Received action: $action for reminder=$reminderId ('$label').")        when (action) {            ACTION_SNOOZE -> handleSnooze(context, reminderId, label, iv, ciphertext)            ACTION_DISMISS -> handleDismiss(context, reminderId)        }    }    /**     * Handle SNOOZE button tap — cancel existing work + re-schedule with snooze delay.     *     * Uses REAL WorkManager APIs:     *   - `cancelAllWorkByTag("reminder_$id")` to kill the current work     *   - `OneTimeWorkRequestBuilder` with `setInitialDelay(snoozeMs, MILLISECONDS)`     *   - `enqueue()` to start the new snoozed work     */    private fun handleSnooze(        context: Context,        reminderId: String,        label: String,        iv: String?,        ciphertext: String?,    ) {        val workTag = "$WORK_TAG_PREFIX$reminderId"        val workManager = WorkManager.getInstance(context)        // 1. Cancel any existing work for this reminder (REAL cancel).        workManager.cancelAllWorkByTag(workTag)        Timber.tag(TAG).d("Cancelled existing work for snooze (tag=$workTag).")        // 2. Build the snoozed work request with 5-minute delay (REAL OneTimeWorkRequest).        val snoozeAtMs = System.currentTimeMillis() + DEFAULT_SNOOZE_MS        val delayMs = DEFAULT_SNOOZE_MS        val workData = workDataOf(            ReminderWorker.KEY_REMINDER_ID to reminderId,            ReminderWorker.KEY_REMINDER_LABEL to label,            ReminderWorker.KEY_REMINDER_IV to (iv ?: ""),            ReminderWorker.KEY_REMINDER_CIPHERTEXT to (ciphertext ?: ""),        )        val snoozeRequest = OneTimeWorkRequestBuilder<ReminderWorker>()            .setInitialDelay(delayMs, TimeUnit.MILLISECONDS)            .addTag(workTag)            .setInputData(workData)            .build()        workManager.enqueue(snoozeRequest)        Timber.tag(TAG).i("Snoozed reminder '$label' (id=$reminderId) for ${DEFAULT_SNOOZE_MS / 60000} min " +                "(fires at ${java.text.SimpleDateFormat("h:mm a", java.util.Locale.getDefault())                    .format(java.util.Date(snoozeAtMs))}).")        // 3. Cancel the current notification (a new one will fire when the snoozed work runs).        cancelNotification(context, reminderId)    }    /**     * Handle DISMISS button tap — cancel WorkManager work + clear notification.     *     * Uses REAL WorkManager.cancelAllWorkByTag().     */    private fun handleDismiss(context: Context, reminderId: String) {        val workTag = "$WORK_TAG_PREFIX$reminderId"        val workManager = WorkManager.getInstance(context)        // 1. Cancel the WorkManager work (REAL cancel).        workManager.cancelAllWorkByTag(workTag)        // 2. Cancel the notification.        cancelNotification(context, reminderId)        Timber.tag(TAG).i("Dismissed reminder (id=$reminderId).")    }    /**     * Cancel the notification for a reminder (REAL NotificationManager.cancel).     */    private fun cancelNotification(context: Context, reminderId: String) {        val notificationManager = context.getSystemService(Context.NOTIFICATION_SERVICE) as? NotificationManager ?: return        val notificationId = ReminderWorker.REMINDER_NOTIFICATION_ID_BASE + (reminderId.hashCode() and 0xFFF)        notificationManager.cancel(notificationId)    }}
